<?php
require_once __DIR__.'/../includes/admin.php';require_role(['super_admin']);$pdo=db();if(is_post()){verify_csrf();$a=$_POST['action']??'';try{if($a==='add'){$u=trim($_POST['username']??'');$p=$_POST['password']??'';$role=in_array($_POST['role']??'', ['super_admin','admin','editor'],true)?$_POST['role']:'editor';if(strlen($p)<8)throw new Exception('Password must be at least 8 characters.');$st=$pdo->prepare('INSERT INTO users(username,password_hash,full_name,role,status) VALUES(?,?,?,?,?)');$st->execute([$u,password_hash($p,PASSWORD_DEFAULT),trim($_POST['full_name']??''),$role,'active']);log_admin("Created user $u");flash('admin_success','User created.');}if($a==='status'){$id=(int)$_POST['id'];$pdo->prepare('UPDATE users SET status=? WHERE id=?')->execute([$_POST['status']??'active',$id]);log_admin("Changed user #$id status");flash('admin_success','User status updated.');}if($a==='delete'){$id=(int)$_POST['id'];if($id===(int)$_SESSION['admin_id'])throw new Exception('You cannot delete your own account.');$pdo->prepare('DELETE FROM users WHERE id=?')->execute([$id]);log_admin("Deleted user #$id");flash('admin_success','User deleted.');}}catch(Throwable $e){flash('admin_error','User error: '.$e->getMessage());}redirect('admin/users.php');}$rows=$pdo->query('SELECT id,username,full_name,role,status,created_at FROM users ORDER BY created_at DESC')->fetchAll();admin_page('Users','users','Super administrators can create accounts and control roles.');admin_flash();?><div class="admin-panel"><h2>Create Admin User</h2><form class="admin-form" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><div class="admin-form-grid three"><label>Username<input name="username" required></label><label>Full name<input name="full_name"></label><label>Password<input type="password" name="password" minlength="8" required></label></div><label>Role<select name="role"><option value="editor">Editor</option><option value="admin">Admin</option><option value="super_admin">Super Admin</option></select></label><button class="btn primary">Create User</button></form></div><div class="admin-panel"><h2>User Accounts</h2><div class="admin-table-wrap"><table class="admin-table"><tr><th>Username</th><th>Name</th><th>Role</th><th>Status</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['username'])?></td><td><?=e($r['full_name'])?></td><td><?=e($r['role'])?></td><td><span class="status <?=e($r['status'])?>"><?=e($r['status'])?></span></td><td><form style="display:inline" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><option>active</option><option>disabled</option></select><button class="btn small outline">Save</button></form> <form style="display:inline" method="post" onsubmit="return confirm('Delete user?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn small" style="background:var(--red);color:#fff">Delete</button></form></td></tr><?php endforeach;?></table></div></div><?php admin_end(); ?>
